const answerRules=[
  ['What is the star number?','76'],
  ['The clue indicates that the next destination is the…','library'],
  ['The next destination is the…','church'],
  ['What is the house number you need to go to on Williams Street?','20'],
  ['The answer to the puzzle is…','racecar'],
  ['I have cracked the code and found the word. It is…','shops'],
  ['The answer is…','tram'],
  ['What is the FINAL answer?','icecream']
];
function chapter(n){const c=C[n];const figures=Array.from({length:c[2]},(_,i)=>`<figure><img src="c${n+1}-${i+1}.jpg" alt="Original Chapter ${n+1} puzzle resource"><figcaption>Original game puzzle resource</figcaption></figure>`).join('');app.innerHTML=wrap(`<div class="topline chapter-nav"><button class="button ghost" onclick="map()">← Case map</button><span class="small">Chapter ${n+1} of 8</span></div><article class="card chapter original"><p class="location">📍 ${c[0]}</p>${fmt(c[1])}<section class="gallery">${figures}</section><section class="answer"><h3>${c[3]}</h3><p>Have you solved the puzzle?</p><button class="button full" onclick="submitAnswer(${n})">Yes — submit our answer</button><details class="hint"><summary>No — I need a hint</summary><p>${fmt(c[4])}</p></details></section></article>`) }
function submitAnswer(n){const r=answerRules[n];app.innerHTML=wrap(`<section class="card answer"><p class="eyebrow">Submit your answer</p><h2>${r[0]}</h2><input id="solution" class="solution" autocomplete="off" placeholder="Your answer"><button class="button full" onclick="checkAnswer(${n})">Submit answer</button><p id="feedback" class="small"></p><button class="button ghost" onclick="chapter(${n})">← Back to puzzle</button></section>`)}
function checkAnswer(n){const entered=document.querySelector('#solution').value.toLowerCase().replace(/[^a-z0-9]/g,'');if(entered.includes(answerRules[n][1])){if(!S.d.includes(n))S.d.push(n);S.u=Math.max(S.u,Math.min(7,n+1));save();map()}else document.querySelector('#feedback').textContent='Incorrect. Review the clue and open the hint room, then try again.'}
window.chapter=chapter;window.submitAnswer=submitAnswer;window.checkAnswer=checkAnswer;

// Chapter 3 has an additional original-form decision before its main clue.
const standardChapter=chapter;
function chapterOneJohnny(){app.innerHTML=wrap(`<div class="topline chapter-nav"><button class="button ghost" onclick="chapter(0)">← Back to Chapter 1</button><span class="small">Chapter 1 of 8</span></div><article class="card chapter original"><h3>76 is right!</h3><p>You are now standing in front of one of the oldest houses in town.</p><p>Do you know the name of the boy who lived in the house with the numbered star during the late 18th century?</p><section class="answer"><button class="button full" onclick="submitJohnnyAnswer()">Yes — submit our answer</button><details class="hint"><summary>No — I need a hint</summary><p><strong>Hint #1: The Legend of the Fruit</strong><br>The boy who grew up in this house went on to travel far and wide across America, planting vast orchards of a crisp, delicious red fruit. Think of his famous nickname!</p><p><strong>Hint #2: The “Hat” Clue</strong><br>This folk hero wore a metal cooking pot on his head and became an iconic apple planter.</p><p><strong>Hint #3</strong><br>His legal name was John Chapman, but he is known by a six-letter nickname: J _ _ _ _ Y.</p></details></section></article>`) }
function submitJohnnyAnswer(){app.innerHTML=wrap(`<section class="card answer"><p class="eyebrow">Submit your answer</p><h2>What was the first name of the boy who grew up in the house with the numbered star in the late 18th century?</h2><input id="solution" class="solution" autocomplete="off" placeholder="6-letter first name / nickname"><button class="button full" onclick="checkJohnnyAnswer()">Submit answer</button><p id="feedback" class="small"></p><button class="button ghost" onclick="chapterOneJohnny()">← Back</button></section>`)}
function checkJohnnyAnswer(){const entered=document.querySelector('#solution').value.toLowerCase().replace(/[^a-z0-9]/g,'');if(entered.includes('johnny'))completeChapter(0);else document.querySelector('#feedback').textContent='Incorrect. Review the hint room, then try again.'}
function chapterFiveRacecar(){const figures=[9,10,11,12].map((n)=>`<figure><img src="asset-original-assets-chapter-5-${n}.jpg" alt="Original Chapter 5 follow-up resource"><figcaption>Original Chapter 5 resource</figcaption></figure>`).join('');app.innerHTML=wrap(`<div class="topline chapter-nav"><button class="button ghost" onclick="chapter(4)">← Back to Chapter 5</button><span class="small">Chapter 5 of 8</span></div><article class="card chapter original"><h3>Racecar?! Race car?! What in the world could that mean?</h3><p>A sudden, deafening roar echoes from behind the police station. A sleek race car screeches into view, its driver hidden behind pitch-black tinted windows. It tears a sharp left onto Williams Street and barrels toward the center of town.</p><p>You spot a hand flash out of the driver window and toss something onto the pavement. Following the tire tracks down Williams Street, you find a crisp handwritten note sitting on the sidewalk: your next clue.</p><section class="gallery">${figures}</section><section class="answer"><h3>Did you find the location of your next test?</h3><button class="button full" onclick="completeChapter(4)">Yes — continue</button><details class="hint"><summary>No — I need a hint</summary><p>The place you are looking for is Ann Scibelli’s memorial, near 134 Williams Street on the median between Williams Street and Parkside Drive.</p></details></section></article>`) }
function chapterTwo(){const figures=Array.from({length:8},(_,i)=>`<figure><img src="asset-original-assets-chapter-2-${i+1}.jpg" alt="Original Chapter 2 resource"><figcaption>Original Chapter 2 resource</figcaption></figure>`).join('');app.innerHTML=wrap(`<div class="topline chapter-nav"><button class="button ghost" onclick="map()">← Case map</button><span class="small">Chapter 2 of 8</span></div><article class="card chapter original"><p class="location">📍 Harold Grinspoon ‘Life’ Sculpture</p><p>Good job completing Chapter 1 and welcome to Chapter 2!</p><p>Start at the Harold Grinspoon <strong>‘Life’</strong> sculpture.</p><h3>The Harold Grinspoon ‘Life’ Sculpture</h3><p>In his mid-80s, renowned local businessman and philanthropist Harold Grinspoon embarked on a third career as an artist, inspired quite by accident when a large cherry tree fell in his Longmeadow backyard. Captivated by its organic form, he chose to transform the fallen timber into a lasting work of art rather than discard it, resulting in a striking 25-foot outdoor sculpture. This initial spark launched a prolific artistic chapter. In the years since, he has produced over a hundred large-scale sculptures crafted from reclaimed trees, with many prominently installed in public spaces and institutions across Massachusetts and nationwide.</p><p>As you expected based on Mrs. Orac’s message, you spot a fresh clue left behind by the thief right in front of the magnificent sculpture.</p><section class="gallery">${figures}</section><section class="answer"><h3>Do you know where the clue is pointing next?</h3><button class="button full" onclick="submitAnswer(1)">Yes — submit our answer</button><details class="hint"><summary>No — I need a hint</summary><p><strong>Hint #1: Focus on the Shapes</strong><br>The clue left at the sculpture has two main elements: floating stars and intercepting lines. They aren’t just placed randomly. Try looking at how these two shapes interact with what you see in the real world.</p><p><strong>Hint #2: Alignment is Key</strong><br>Not all stars are created equal. Some stars perfectly align and overlap with the circular orbs, while others float completely off-center. The intercepting lines indicate where branches cross. Are you looking at the sculpture and clue from where the clue was found?</p><p><strong>Hint #3: Filtering Out The Noise</strong><br>Try filtering out the noise: what happens if you only look at the letters attached to stars that perfectly line up with an orb?</p><p><strong>Hint #4: Where to Next?</strong><br>The stars that perfectly align with the orbs spell a 7-letter word indicating your next physical destination. Read the letters from left to right.</p><p><strong>Hint #5: The solved puzzle</strong><br>Make your way to Storrs Library and see what you can find there.</p></details></section></article>`) }
function chapterThreeStart(){app.innerHTML=wrap(`<div class="topline chapter-nav"><button class="button ghost" onclick="map()">← Case map</button><span class="small">Chapter 3 of 8</span></div><article class="card chapter original"><p class="location">📍 Storrs Library</p><h3>Welcome to Storrs Library!</h3><p>In 1907, <strong>Sarah Williams Storrs</strong>—granddaughter of the town's second pastor, Richard Salter Storrs—donated the Storrs Estate and property in her will. This generous gift led to the establishment of the Richard Salter Storrs Library Association in 1910.</p><p>The initial home of the Richard Salter Storrs Library was established in the historic Storrs House at 697 Longmeadow Street. When the current library building was constructed in 1932, the historic house was physically moved a short distance to the south to make room for it, where it now serves as the Storrs House Museum and Archive for the Longmeadow Historical Society.</p><p>While the library has changed locations over the years, the presence of <strong>Reverend Richard Salter Storrs</strong> and several of his family members can still be felt inside.</p><section class="answer"><h3>Are you able to enter the library and look for the family portraits?</h3><button class="button full" onclick="chapterThreeClue()">Yes — we found the portraits</button><button class="button ghost full" onclick="showChapterThreePortraits()">No — show us the portraits</button></section></article>`) }
function showChapterThreePortraits(){const figures=[1,2,3,4].map((n,i)=>`<figure><img src="asset-original-assets-chapter-3-${n}.jpg" alt="Chapter 3 portrait ${i+1}"><figcaption>Portrait #${i+1}</figcaption></figure>`).join('');app.innerHTML=wrap(`<div class="topline chapter-nav"><button class="button ghost" onclick="chapterThreeStart()">← Back</button><span class="small">Chapter 3 of 8</span></div><article class="card chapter original"><h3>The portraits inside the library</h3><p>Use these portraits if you cannot enter the library. The clue will still require you to identify the Storrs family members.</p><section class="gallery">${figures}</section><button class="button full" onclick="chapterThreeClue()">Continue to the clue</button></article>`) }
function chapterThreeClue(){app.innerHTML=wrap(`<div class="topline chapter-nav"><button class="button ghost" onclick="chapterThreeStart()">← Back</button><span class="small">Chapter 3 of 8</span></div><article class="card chapter original"><h3>Good job! You have located the four portraits.</h3><p>As you wonder what to do with your newfound observations, a librarian notices you studying the portraits and approaches.</p><p>“Excuse me,” she says quietly. “A woman came in just before you did and asked me to give this piece of paper to anyone who was examining these portraits. She left in such a hurry that I didn't even have time to ask her any questions, but she insisted that you would need this.”</p><p>She hands you the folded slip of paper and leaves you to your investigation.</p><section class="answer"><h3>Did you uncover your next destination?</h3><button class="button full" onclick="submitAnswer(2)">Yes — submit our answer</button><details class="hint"><summary>No — I need a hint</summary><p><strong>Hint #1: Who is Who?</strong> Reverend Richard Salter Storrs (1763–1819) wears an older 18th-century black clerical robe with white collar tabs. Reverend Richard S. Storrs of Brooklyn (1821–1900) has prominent white mutton-chop sideburns. Mary Elwell (Jenks) Storrs is the elegant woman in the gold frame. Professor Richard S. Storrs wears a 19th-century suit and is in black and white.</p><p><strong>Hint #2:</strong> After identifying the people, use the red letters associated with them on the Storrs family-tree clue. Read the portraits from left to right.</p></details></section></article>`) }
function chapterFour(){const figures=Array.from({length:10},(_,i)=>`<figure><img src="asset-original-assets-chapter-4-${i+1}.jpg" alt="Original Chapter 4 resource"><figcaption>Original Chapter 4 resource</figcaption></figure>`).join('');app.innerHTML=wrap(`<div class="topline chapter-nav"><button class="button ghost" onclick="map()">← Case map</button><span class="small">Chapter 4 of 8</span></div><article class="card chapter original"><p class="location">📍 First Church of Christ</p><p>Good job completing Chapter 3 and welcome to Chapter 4!</p><h3>The First Church</h3><p><strong>The First Pastor’s Captivity:</strong> Long before the current building rose, the church’s first minister was Reverend Stephen Williams, who settled here in 1716. As a young boy, Williams survived the 1704 Deerfield raid and was marched to Canada before being ransomed.</p><p><strong>The Human Alarm Clock:</strong> Before the church got its first bell in 1743, Longmeadow paid Nathaniel Burt 10 shillings a year to walk the street beating a drum to announce services.</p><p><strong>The Great Building Migration:</strong> The current 1768 structure originally stood on the Green, where the flagpole is today. In 1873, the entire church was moved to its present location.</p><p><strong>A Paul Revere Connection:</strong> The congregation purchased a replacement bell directly from Paul Revere in Boston in 1809.</p><h3>The panicked groom</h3><p>You are standing in front of the big white church when a man in a sharp tuxedo approaches you in a total panic. A strange woman shoved two enigmatic papers into his hands; he is getting married and has lost his bride. He gives you the papers so he can search for her.</p><section class="gallery">${figures}</section><section class="answer"><h3>Do you know where to go next?</h3><button class="button full" onclick="submitAnswer(3)">Yes — submit our answer</button><details class="hint"><summary>No — I need a hint</summary><p><strong>Hint #1: Where do I start?</strong><br>Find the true/false answers at red-star houses, street signs with the town seal, the Green behind the war memorials, the witness stones, and the memorial plaques.</p><p><strong>Hint #3: What are the T/F answers?</strong><br>1T, 2T, 3T, 4F, 5T, 6F, 7F, 8F, 9F.</p><p><strong>Hint #4: Now what?!</strong><br>Use the correct answers to connect the dots. Pay attention to the number and color pairs.</p><p><strong>Hint #5: How do I connect the dots?</strong><br>Statement 1 is true, so start with the green dot marked 1, then use the green dot marked 2, and continue through all nine dots to reveal the solution.</p></details></section></article>`) }
chapter=function(n){return n===1?chapterTwo():n===2?chapterThreeStart():n===3?chapterFour():standardChapter(n)};
