function hintPanel(chapter){const count=revealedHints[chapter]||0;const hints=chapterHints[chapter];const shown=hints.slice(0,count).map(text=>`<p>${text}</p>`).join('');const control=count<hints.length?`<button class="button ghost full" onclick="revealNextHint(${chapter})">${count?'Show another hint':'I need a hint'}</button>`:'<p class="small"><strong>No more hints available</strong></p>';return `<section class="hint-progress">${shown}${control}</section>`}
function revealNextHint(chapter){revealedHints[chapter]=Math.min((revealedHints[chapter]||0)+1,chapterHints[chapter].length);localStorage.setItem('staff-ministry-hints',JSON.stringify(revealedHints));if(chapter===1)chapterTwo();else if(chapter===2)chapterThreeClue();else if(chapter===3)chapterFour();else window.chapter(chapter);requestAnimationFrame(()=>requestAnimationFrame(()=>window.scrollTo({top:document.body.scrollHeight,behavior:'auto'})))}

