chapterSix=function(){app.innerHTML=wrap(`<div class="topline chapter-nav"><button class="button ghost" onclick="map()">← Case map</button><span class="small">Chapter 6 of 8</span></div><article class="card chapter original"><p class="location">📍 Ann Scibelli’s Memorial</p><p>Good job completing Chapter 5 and welcome to Chapter 6!</p><h3>A Place to Rest, Reflect and Renew</h3><p>You are now standing in front of Ann Scibelli's memorial stone. Ann was a beloved member of the Longmeadow community. Looking around, you notice a small, <strong>colorful piece of paper</strong> wedged neatly between two pavers. You carefully pull it free and examine it. What could that mean? You pull out your notebook, study the pattern, and start putting the pieces together...</p><section class="gallery"><figure><img src="asset-original-assets-chapter-6-1.jpg" alt="Map to Ann Scibelli’s Memorial"><figcaption>Map to Ann Scibelli’s Memorial</figcaption></figure><figure><img src="asset-original-assets-chapter-6-2.jpg" alt="Ann Scibelli’s Memorial"><figcaption>Ann Scibelli’s Memorial</figcaption></figure><figure><img src="c6-1.jpg" alt="Piece of paper found between two pavers, front"><figcaption>Piece of paper found between two pavers (front)</figcaption></figure><figure><img src="c6-2.jpg" alt="Piece of paper found between two pavers, back"><figcaption>Piece of paper found between two pavers (back)</figcaption></figure></section><section class="answer"><h3>Did you crack the code and know where to go next?</h3><button class="button full" onclick="submitAnswer(5)">Yes — submit our answer</button>${hintPanel(5)}</section></article>`) };
