function home(){const hasProgress=S.u>0||S.d.length>0;app.innerHTML=wrap(`<section class="card original"><h2>Get ready for a <strong>FREE, interactive, historical mystery adventure through Longmeadow!</strong></h2><p>Welcome! We are a local Longmeadow family who loves puzzles, outdoor adventures, and our town’s rich history! We built this interactive mystery trail so neighbors, friends, and families could explore Longmeadow in a fun, new way together.</p><p><strong>How to play:</strong> Start at Bliss Park Playground, follow clues from destination to destination, use hints when needed, and bring a charged phone plus pencil and paper.</p><p>🚲 Consider bikes or scooters: the adventure spans 8 destinations across a 4-mile trail. Travel safely, respect private property, and play at your own pace.</p><button class="button full" onclick="map()">${hasProgress?'Continue the adventure':'Begin the adventure'}</button><button class="button ghost full restart-adventure" onclick="restartAdventurePrompt()">Restart from the beginning</button></section>`)}
window.home=home;home();

// Chapter 1 also uses the progressive hint/solution treatment.
chapterHints[0]=['<strong>Hint #1</strong><br>Take a close look at the back of the cryptic note. The message points straight to your first destination!'];
const chapterWithEverySolution=chapter;chapter=function(n){chapterWithEverySolution(n);if(n===0){const old=document.querySelector('.answer details.hint');if(old)old.outerHTML=hintPanel(0)}};window.chapter=chapter;

// Images that explain a hint appear with that hint as it is revealed.
const hintImages={
  0:{0:[['c1-3.jpg','The cryptic note (back)']]},
  1:{0:[['asset-original-assets-chapter-2-4.jpg','The clue left in front of the sculpture'],['asset-original-assets-chapter-2-5.jpg','The view from where the clue was left']],1:[['asset-original-assets-chapter-2-7.jpg','The clue and the sculpture']],4:[['asset-original-assets-chapter-2-8.jpg','Map to Storrs Library']]},
  2:{0:[['asset-chapter3-clue-front.jpg','Folded slip of paper (front)'],['asset-chapter3-clue-back.jpg','Folded slip of paper (back)']]},
  3:{0:[['asset-original-assets-chapter-4-5.jpg','Enigmatic paper #1'],['asset-original-assets-chapter-4-6.jpg','Enigmatic paper #2']],1:[['asset-original-assets-chapter-4-7.jpg','Some visual clues']]},
  4:{0:[['asset-original-assets-chapter-5-6.jpg','The scroll pediment at 20 Williams Street'],['asset-original-assets-chapter-5-3.jpg','Slip of paper wedged into the bench frame']]},
  5:{0:[['c6-1.jpg','Piece of paper found between two pavers (front)'],['c6-2.jpg','Piece of paper found between two pavers (back)']]},
  6:{0:[['asset-original-assets-chapter-7-5.jpg','The Ding-Ding clue'],['asset-original-assets-chapter-7-6.jpg','Razzmatazz Kids store front']],2:[['asset-original-assets-chapter-7-7.jpg','The Longmeadow trolley']]},
  7:{0:[['asset-original-assets-chapter-8-5.jpg','The stack of Polaroids']]}
};
function hintImageGallery(chapter,index){const images=hintImages[chapter]?.[index]||[];if(!images.length)return '';return `<section class="gallery hint-images">${images.map(([src,label])=>`<figure><img src="${src}" alt="${label}"><figcaption>${label}</figcaption></figure>`).join('')}</section>`}
hintPanel=function(chapter){const count=revealedHints[chapter]||0;const hints=chapterHints[chapter]||[];const shown=hints.slice(0,count).map((text,index)=>`<p>${text}</p>${hintImageGallery(chapter,index)}`).join('');let control='';if(count<hints.length)control=`<button class="button ghost full" onclick="revealNextHint(${chapter})">${count?'Show another hint':'I need a hint'}</button>`;else if(revealedSolutions[chapter])control=`<p class="solution-reveal"><strong>Solution: ${chapterSolutions[chapter]}</strong></p>`;else control=`<button class="button ghost full" onclick="revealSolution(${chapter})">Just show me the solution!</button>`;return `<section class="hint-progress">${shown}${control}</section>`};

// Chapter 4's source page removes its spoiler image from the main clue page; restore it only after Hint #2 is revealed.
const chapterFourWithHintImageFix=chapterFour;
chapterFour=function(){chapterFourWithHintImageFix();if((revealedHints[3]||0)>=2&&!document.querySelector('.chapter-four-hint-two-image')){const secondHint=document.querySelector('.hint-progress > p:nth-of-type(2)');secondHint?.insertAdjacentHTML('afterend','<section class="gallery hint-images chapter-four-hint-two-image"><figure><img src="asset-original-assets-chapter-4-7.jpg" alt="Some visual clues"><figcaption>Some visual clues</figcaption></figure></section>')}};
window.chapterFour=chapterFour;

// Keep answers concealed until the player chooses the dedicated solution button.
chapterHints[0]=['<strong>Hint #1</strong><br>Take a close look at the back of the cryptic note. The message points straight to your first destination!'];
chapterHints[1][4]='<strong>Hint #5: The solved puzzle</strong><br>You now have enough information to identify the next destination. If you would prefer the answer, use the button below.';

// Chapter 2’s later visual resources stay hidden until the corresponding hint reveals them.
const chapterTwoWithImageTiming=chapterTwo;
chapterTwo=function(){chapterTwoWithImageTiming();document.querySelectorAll('img[src$="asset-original-assets-chapter-2-7.jpg"],img[src$="asset-original-assets-chapter-2-8.jpg"]').forEach(image=>{if(!image.closest('.hint-progress'))image.closest('figure')?.remove()})};
window.chapterTwo=chapterTwo;

// Correct the Chapter 1 resource captions to match the actual images.
Object.assign(imageLabels,{
  'c1-1.jpg':'The cryptic note (front)',
  'c1-2.jpg':'The cryptic note (back)',
  'c1-3.jpg':'Mr. Potato Head'
});
hintImages[0][0]=[['c1-2.jpg','The cryptic note (back)']];

// Never put a final answer in hint text; that is shown only after the player presses the solution button.
chapterHints[1][4]='<strong>Hint #5: The solved puzzle</strong><br>You now have enough information to identify the next destination. If you would prefer the answer, use the button below.';
chapterHints[2][2]='<strong>Hint #3: Put the letters in the correct order</strong><br>Work through the portraits from left to right, matching each person with the red letter on the folded family-tree clue. You now have enough information to identify the next destination. If you would prefer the answer, use the button below.';
chapterHints[3][5]='<strong>Hint #6: The solved puzzle</strong><br>You now have enough information to identify the house number on Williams Street. If you would prefer the answer, use the button below.';
chapterHints[4][3]='<strong>Hint #4: Solved puzzle</strong><br>You now have enough information to identify the palindrome. If you would prefer the answer, use the button below.';
chapterHints[5][3]='<strong>Hint #4: Colors</strong><br>Use the sequence of colors for the 5-letter code at the bottom of the clue to arrange the letters you extracted. You now have enough information to identify the final word. If you would prefer the answer, use the button below.';
chapterHints[6][3]='<strong>Hint #4</strong><br>You now have enough information to identify the 4-letter word. If you would prefer the answer, use the button below.';
chapterHints[7][3]='<strong>Hint #4: The Polaroid answers</strong><br>Identify each business and use the number on its Polaroid to select the corresponding letter. You now have enough information to identify the final answer. If you would prefer the answer, use the button below.';

// Older test runs may have saved revealed solutions. Clear that old state once so a fresh run never shows answers automatically.
if(localStorage.getItem('staff-ministry-solution-state-version')!=='2'){Object.keys(revealedSolutions).forEach(key=>delete revealedSolutions[key]);localStorage.setItem('staff-ministry-solutions',JSON.stringify(revealedSolutions));localStorage.setItem('staff-ministry-solution-state-version','2')}
function confirmRestartAdventure(){S.u=0;S.d=[];Object.keys(revealedHints).forEach(key=>delete revealedHints[key]);Object.keys(revealedSolutions).forEach(key=>delete revealedSolutions[key]);localStorage.setItem('staff-ministry-progress',JSON.stringify(S));localStorage.setItem('staff-ministry-hints',JSON.stringify(revealedHints));localStorage.setItem('staff-ministry-solutions',JSON.stringify(revealedSolutions));home()}
window.confirmRestartAdventure=confirmRestartAdventure;
